<section id="quiz"><div class="wrap"><div class="head reveal"><div><div class="kicker">AI QUIZ ZONE</div><h2>Test what you know.</h2></div><p>Tap an answer and get instant feedback. Restart anytime.</p></div><div class="quiz-grid"><article class="quiz-card reveal" data-answer="A"><h3>1. Which prompt is stronger?</h3><button data-v="A">A. A clear goal + context + constraints + format</button><button data-v="B">B. Only “do it”</button><p class="quiz-result"></p></article><article class="quiz-card reveal" data-answer="A"><h3>2. Should important AI facts be verified?</h3><button data-v="A">A. Yes</button><button data-v="B">B. No</button><p class="quiz-result"></p></article><article class="quiz-card reveal" data-answer="A"><h3>3. What should you avoid sharing unnecessarily?</h3><button data-v="A">A. Passwords and OTPs</button><button data-v="B">B. Public topic names</button><p class="quiz-result"></p></article><article class="quiz-card reveal" data-answer="A"><h3>4. What does hallucination mean here?</h3><button data-v="A">A. Confident but incorrect AI output</button><button data-v="B">B. Faster internet</button><p class="quiz-result"></p></article><article class="quiz-card reveal" data-answer="A"><h3>5. Best role for AI in high-stakes work?</h3><button data-v="A">A. Assistant with human review</button><button data-v="B">B. Final unquestioned authority</button><p class="quiz-result"></p></article></div><button class="btn" id="resetQuiz">Reset Quiz</button></div></section>
<section id="nepali"><div class="wrap"><div class="head reveal"><div><div class="kicker">नेपाली AI CLASS</div><h2>AI सिकौँ — सरल नेपालीमा।</h2></div><p>शून्य स्तरबाट practical AI literacy, prompting र सुरक्षित प्रयोगसम्म।</p></div><div class="lesson-grid"><article class="lesson reveal"><b>Lesson 01</b><h3>AI भनेको के हो?</h3><p>AI ले data र patterns प्रयोग गरेर text, image, code जस्ता काममा सहयोग गर्न सक्छ।</p></article><article class="lesson reveal"><b>Lesson 02</b><h3>Prompt कसरी लेख्ने?</h3><p>Goal, context, constraint र output format स्पष्ट लेख्दा उत्तर उपयोगी हुन्छ।</p></article><article class="lesson reveal"><b>Lesson 03</b><h3>AI को उत्तर सधैं सही हुन्छ?</h3><p>हुँदैन। महत्वपूर्ण तथ्य, रकम, कानून, स्वास्थ्य वा निर्णयमा स्रोतबाट verify गर्नुपर्छ।</p></article><article class="lesson reveal"><b>Lesson 04</b><h3>Privacy किन महत्त्वपूर्ण?</h3><p>Password, OTP, नागरिकता नम्बर, बैंक विवरण वा गोप्य data अनावश्यक रूपमा AI मा नदिनुहोस्।</p></article><article class="lesson reveal"><b>Lesson 05</b><h3>Study मा AI</h3><p>AI लाई tutor जस्तो प्रयोग गरेर explanation, quiz, example र revision plan माग्न सकिन्छ।</p></article><article class="lesson reveal"><b>Lesson 06</b><h3>Excel + AI</h3><p>Formula explanation, sample data, cleaning steps र report ideas माग्न सकिन्छ; result Excel मा verify गर्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 07</b><h3>Content Creation</h3><p>Idea, outline, caption र script draft बनाउन AI उपयोगी हुन्छ; final voice आफ्नै बनाउनुहोस्।</p></article><article class="lesson reveal"><b>Lesson 08</b><h3>Coding with AI</h3><p>Code explain, debug र practice गराउन सकिन्छ; unknown code run गर्नु अघि review गर्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 09</b><h3>Image AI</h3><p>Subject, setting, lighting, camera, composition र style स्पष्ट गर्दा prompt बलियो हुन्छ।</p></article><article class="lesson reveal"><b>Lesson 10</b><h3>Research</h3><p>AI बाट keywords र outline लिनुहोस्, तर primary/reliable sources आफैं जाँच्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 11</b><h3>Business AI</h3><p>FAQ, draft, inventory ideas, reports र templates मा प्रयोग गर्न सकिन्छ।</p></article><article class="lesson reveal"><b>Lesson 12</b><h3>Email AI</h3><p>Tone, purpose, recipient र key points दिएर professional draft बनाउन सकिन्छ।</p></article><article class="lesson reveal"><b>Lesson 13</b><h3>Presentation AI</h3><p>Audience, duration र objective दिएर slide outline र speaker notes बनाउन सकिन्छ।</p></article><article class="lesson reveal"><b>Lesson 14</b><h3>AI Hallucination</h3><p>AI ले confident भएर गलत कुरा पनि भन्न सक्छ; verification आवश्यक हुन्छ।</p></article><article class="lesson reveal"><b>Lesson 15</b><h3>Prompt सुधार</h3><p>पहिलो उत्तर कमजोर भए critique, missing details र revised version माग्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 16</b><h3>Role Prompt</h3><p>“Act as a teacher/data analyst…” ले perspective दिन्छ, तर expertise verify गर्नुपर्छ।</p></article><article class="lesson reveal"><b>Lesson 17</b><h3>Output Format</h3><p>Table, bullets, JSON, checklist वा step-by-step जस्तो format पहिले नै भन्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 18</b><h3>Automation</h3><p>Repeated digital tasks workflow मा जोड्न सकिन्छ; permissions र errors monitor गर्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 19</b><h3>Responsible AI</h3><p>Fairness, privacy, copyright र human responsibility ध्यानमा राख्नुहोस्।</p></article><article class="lesson reveal"><b>Lesson 20</b><h3>30-Day AI Plan</h3><p>हरेक दिन एउटा concept, एउटा prompt र एउटा practical task अभ्यास गर्नुहोस्।</p></article></div></div></section>
<section id="coach"><div class="wrap"><div class="head reveal"><div><div class="kicker">CHATBOT-STYLE LEARNING</div><h2>Prabin AI Coach.</h2></div><p>This local learning coach answers built-in AI learning questions. It does not call an external AI API.</p></div><div class="coach reveal"><div id="coachChat" class="coach-chat"><div class="bubble bot">Namaste 👋 Ask me about prompts, AI basics, privacy, study, Excel + AI or responsible AI.</div></div><div class="coach-chips"><button>What is AI?</button><button>Make a strong prompt</button><button>AI for Excel</button><button>AI privacy</button><button>AI study plan</button></div><div class="coach-input"><input id="coachInput" placeholder="Ask an AI learning question..."><button class="btn primary" id="coachSend">Send</button></div></div></div></section><section id="roadmap"><div class="wrap"><div class="head reveal"><div><div class="kicker">AI ROADMAP</div><h2>Zero to confident AI user.</h2></div><p>A simple learning order that focuses on durable skills rather than chasing every new tool.</p></div><div class="timeline"><article class="step reveal"><b>1</b><h3>Understand AI</h3><p>Learn AI basics, strengths, limits, hallucinations and privacy awareness.</p></article><article class="step reveal"><b>2</b><h3>Master Prompts</h3><p>Practice goal, context, constraints, examples and output formats.</p></article><article class="step reveal"><b>3</b><h3>Build Workflows</h3><p>Use AI for study, writing, data, Office work, planning and content.</p></article><article class="step reveal"><b>4</b><h3>Verify & Refine</h3><p>Fact-check important outputs, test assumptions and iterate deliberately.</p></article><article class="step reveal"><b>5</b><h3>Create Projects</h3><p>Turn skills into useful mini-projects, lessons, templates and automations.</p></article></div></div></section><section><div class="wrap"><div class="quote reveal"><div class="kicker">AI MINDSET</div><blockquote>“Don’t just ask AI for answers. Learn how to think, direct, verify and create with it.”</blockquote><p>— Prabin AI Lab</p></div></div></section></main><footer><div class="wrap">© <?= $year ?> Prabin AI Lab • Designed for practical AI learning by Prabin Chaudhary</div></footer><button class="top" id="top">↑</button><script>
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');$$('.bar i',e.target).forEach(b=>b.style.width=b.dataset.w||'0%')}}),{threshold:.08});$$('.reveal').forEach(x=>io.observe(x));
$('#generate').onclick=()=>{let r=$('#role').value,g=$('#goal').value.trim(),s=$('#style').value;$('#out').textContent=`Act as an ${r}.

GOAL: ${g}

CONTEXT: Ask me up to 3 useful questions if important context is missing.

METHOD:
1. Understand the goal before answering.
2. Explain your reasoning at a useful summary level.
3. Give practical steps and examples.
4. Point out uncertainty or assumptions.
5. End with a small action I can do now.

OUTPUT STYLE: ${s}.
LANGUAGE: Clear, simple English unless I request another language.`};
$('#copy').onclick=async()=>{await navigator.clipboard.writeText($('#out').textContent);$('#copy').textContent='Copied ✓';setTimeout(()=>$('#copy').textContent='Copy Prompt',1200)};
$('#improve').onclick=()=>{$('#out').textContent += `\n\nQUALITY CHECK: Before finalizing, critique your first draft for clarity, accuracy, missing context and usefulness, then provide an improved final version.`;};
let active='All';function filterTips(){let q=$('#tipSearch').value.toLowerCase();$$('.tip').forEach(x=>x.style.display=((active==='All'||x.dataset.cat===active)&&x.dataset.text.includes(q))?'':'none')}$('#tipSearch').oninput=filterTips;$$('#filters button').forEach(b=>b.onclick=()=>{$$('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');active=b.dataset.cat;filterTips()});
$('#promptSearch').oninput=e=>{let q=e.target.value.toLowerCase();$$('.prompt-card').forEach(x=>x.style.display=x.dataset.text.includes(q)?'':'none')};$$('.copy-template').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText($('p',b.parentElement).textContent);b.textContent='Copied ✓';setTimeout(()=>b.textContent='Copy',1000)});
window.addEventListener('scroll',()=>$('#top').classList.toggle('show',scrollY>500));$('#top').onclick=()=>scrollTo({top:0,behavior:'smooth'});

// Expanded AI platform interactions
const gs=document.getElementById('glossSearch'); if(gs) gs.addEventListener('input',()=>{const q=gs.value.toLowerCase();document.querySelectorAll('#glossGrid .gloss').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'block':'none')});
document.querySelectorAll('.quiz-card button').forEach(b=>b.addEventListener('click',()=>{const c=b.closest('.quiz-card'),ok=b.dataset.v===c.dataset.answer;c.querySelector('.quiz-result').textContent=ok?'Correct ✓':'Try again — review the AI basics section.';}));
const rq=document.getElementById('resetQuiz'); if(rq) rq.onclick=()=>document.querySelectorAll('.quiz-result').forEach(x=>x.textContent='');
const answers={ai:'AI is technology that can recognize patterns, generate content and assist with tasks. Keep human judgment and verification in the loop.',prompt:'Strong prompt formula: Role + Goal + Context + Constraints + Output Format + Example. Ask the AI to clarify missing information.',excel:'For Excel, ask AI to explain formulas, create sample datasets, suggest cleaning steps or troubleshoot formulas. Verify the final formula in Excel.',privacy:'Do not unnecessarily share passwords, OTPs, banking details, identity numbers or confidential data. Check the privacy policy of the AI service you use.',study:'Study workflow: learn one concept → ask for a simple explanation → request examples → take a quiz → explain it back → verify important facts.'};
function coachReply(q){q=q.toLowerCase();if(q.includes('prompt'))return answers.prompt;if(q.includes('excel'))return answers.excel;if(q.includes('privacy')||q.includes('safe'))return answers.privacy;if(q.includes('study')||q.includes('learn'))return answers.study;if(q.includes('ai'))return answers.ai;return 'I am a built-in learning coach, not a live AI model. Try asking about AI basics, prompts, Excel + AI, privacy, or an AI study plan.'}
function sendCoach(text){if(!text)return;const chat=document.getElementById('coachChat');chat.insertAdjacentHTML('beforeend','<div class="bubble user"></div>');chat.lastElementChild.textContent=text;setTimeout(()=>{chat.insertAdjacentHTML('beforeend','<div class="bubble bot"></div>');chat.lastElementChild.textContent=coachReply(text);chat.scrollTop=chat.scrollHeight},180);chat.scrollTop=chat.scrollHeight}
const ci=document.getElementById('coachInput'),cs=document.getElementById('coachSend');if(cs)cs.onclick=()=>{sendCoach(ci.value.trim());ci.value=''};if(ci)ci.addEventListener('keydown',e=>{if(e.key==='Enter')cs.click()});document.querySelectorAll('.coach-chips button').forEach(b=>b.onclick=()=>sendCoach(b.textContent));
</script></body></html>